def obrabotat_diagnostiku(html, kod):
    """Страница UA-XXXX-diag.html: если в CRM есть отчёт (diag_link/diag_text),
    а страница показывает заглушку — материалы выводятся клиенту."""
    if not html or "mcf-diag-block" in html:
        return html
    m = dannye(kod)
    link = ("%s" % (m.get("diag_link") or "")).strip()
    tekst = ("%s" % (m.get("diag_text") or "")).strip()
    if not link and not tekst:
        return html
    chasti = ['<div class="mcf-diag-block" style="' + _O + '">',
              '<div style="' + _Z + '">Результаты комплексной диагностики</div>']
    if link:
        chasti.append(
            '<div style="margin:10px 0"><a href="%s" target="_blank" rel="noopener" '
            'style="display:inline-block;padding:11px 16px;border-radius:12px;'
            'background:rgba(212,175,55,.20);border:1px solid rgba(212,175,55,.55);'
            'color:#f4e3ae;font-weight:800;text-decoration:none">'
            'Открыть отчёт компьютерной диагностики →</a></div>' % link)
    if tekst:
        bezopasno = (tekst.replace("&", "&amp;").replace("<", "&lt;")
                     .replace(">", "&gt;"))
        chasti.append('<div style="white-space:pre-line;margin-top:8px">%s</div>' % bezopasno)
    chasti.append("</div>")
    blok = "".join(chasti)
    for yakor in ("Материалы комплексной диагностики пока не добавлены.",
                  "Материалы диагностики пока не добавлены",
                  "Данные диагностики пока не добавлены."):
        if yakor in html:
            return html.replace(yakor, blok, 1)
    if "</body>" in html:
        return html.replace("</body>", blok + "</body>", 1)
    return html + blok

def proverit(html, kod=''):
    errors = list(_ua_seo068_original_proverit(html, kod) or [])
    file_name = (str(kod).upper() + '.html') if kod else _ua_seo068_core_path(html)
    if file_name:
        expected = _UA_SEO068_ORIGIN + '/video/' + file_name
        canonicals = _ua_seo068_re.findall(r'<link\b(?=[^>]*\brel\s*=\s*["\'][^"\']*canonical[^"\']*["\'])(?=[^>]*\bhref\s*=\s*["\']([^"\']+)["\'])[^>]*>', str(html), _ua_seo068_re.I)
        if canonicals != [expected]:
            errors.append('SEO068 canonical')
        if _ua_seo068_re.search(r'<meta\b(?=[^>]*\bname\s*=\s*["\'](?:robots|googlebot)["\'])[^>]*\bcontent\s*=\s*["\'][^"\']*(?:noindex|nofollow)', str(html), _ua_seo068_re.I):
            errors.append('SEO068 robots')
        if kod:
            identifier = str(kod).upper()
            primary = []
            for found in _UA_SEO068_ACTION.finditer(str(html)):
                opening = found.group(1)
                visible = _ua_seo068_strip(found.group('inner'))
                if 'kn_kupit' in _ua_seo068_attr(opening, 'class').split() or _UA_SEO068_CTA_RE.search(visible):
                    primary.append(visible)
            if primary != [_UA_SEO068_CTA]:
                errors.append('SEO068 CTA')
            diagnostics = []
            for tag in _ua_seo068_re.findall(r'<a\b[^>]*>', str(html), _ua_seo068_re.I):
                href = _ua_seo068_attr(tag, 'href')
                match = _ua_seo068_re.search(r'(UA-[0-9]{4,}-diag\.html)(?:[?#]|$)', href, _ua_seo068_re.I)
                if match:
                    diagnostics.append(match.group(1).upper())
            if diagnostics != [identifier + '-DIAG.HTML']:
                errors.append('SEO068 diagnostics')
    result = []
    for error in errors:
        if error not in result:
            result.append(error)
    return result

